from collections import defaultdict
from fractions import Fraction
import json

r,q=5,6
F=[(2,2),(3,2),(3,3),(4,2),(4,3),(5,2),(4,4),(5,3),(5,4),(5,5)]
F=set(F)

def parts_box(maxpart,maxlen,minsum=0):
    out=[]
    def rec(prev,rem,cur):
        if len(cur)==maxlen:
            t=tuple(x for x in cur if x)
            if sum(t)>=minsum: out.append(t)
            return
        for x in range(min(prev,rem),-1,-1):
            rec(x,rem-x,cur+[x])
    # enumerate by bounded weak sequences directly
    def go(prev,cur):
        if len(cur)==maxlen:
            t=tuple(x for x in cur if x)
            if sum(t)>=minsum: out.append(t)
            return
        for x in range(prev,-1,-1): go(x,cur+[x])
    go(maxpart,[])
    return out

def degree(p): return sum(p)
def contains22(p): return len(p)>=2 and p[0]>=2 and p[1]>=2
def pad(p): return p+(0,)*(r-len(p))
def horizontal(mu,nu):
    a,b=pad(mu),pad(nu)
    return all(b[i]>=a[i] for i in range(r)) and all(b[i+1]<=a[i] for i in range(r-1))
def ps(p): return ''.join(map(str,p)) if p else '0'
def rid(k,mu): return f'({k};{ps(mu)})'

allp=parts_box(q,r)
cols=sorted([p for p in allp if contains22(p)], key=lambda p:(degree(p),p))
bydeg=defaultdict(list)
for c in cols: bydeg[degree(c)].append(c)
colindex={c:i for i,c in enumerate(cols)}

rows=[]
for mu in cols:
    for k in range(1,q+1):
        target=[nu for nu in allp if degree(nu)==degree(mu)+k and horizontal(mu,nu)]
        if target:
            rows.append((k,mu,tuple(sorted(target))))
rows.sort(key=lambda x:(degree(x[1])+x[0],x[0],x[0][1],x[2]))
assert len(cols)==431, len(cols)
assert len(rows)==2130, len(rows)
assert F <= set(cols) and len(F)==10

# Sparse vectors keyed by column partition.  For each degree select unit pivots,
# then back-eliminate so every transformed pivot relation is pivot + F-tail.
pivots={}
selected=[]
block_records=[]

def axpy(v,a,w):
    # v <- v-a*w
    for c,x in w.items():
        y=v.get(c,0)-a*x
        if y: v[c]=y
        elif c in v: del v[c]

def bareiss_det(A):
    n=len(A)
    if n==0:return 1
    B=[row[:] for row in A]
    sign=1; prev=1
    for k in range(n-1):
        z=next((i for i in range(k,n) if B[i][k]),None)
        if z is None:return 0
        if z!=k: B[k],B[z]=B[z],B[k]; sign=-sign
        piv=B[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n):
                num=B[i][j]*piv-B[i][k]*B[k][j]
                assert num%prev==0
                B[i][j]=num//prev
        prev=piv
        for i in range(k+1,n): B[i][k]=0
    return sign*B[-1][-1]

for d in sorted(bydeg):
    C=bydeg[d]
    free=sorted([c for c in C if c in F])
    nonfree=[c for c in C if c not in F]
    R=[x for x in rows if degree(x[1])+x[0]==d]
    local={}
    chosen=[]
    # scan repeatedly. Each chosen raw Pieri row is transformed using earlier pivots.
    pending=list(R)
    progress=True
    while pending and len(local)<len(nonfree) and progress:
        progress=False
        newpending=[]
        for row in pending:
            k,mu,tgt=row
            v={c:1 for c in tgt}
            for pc,pv in local.items():
                a=v.get(pc,0)
                if a: axpy(v,a,pv['vec'])
            candidate=next((c for c in nonfree if c not in local and abs(v.get(c,0))==1),None)
            if candidate is None:
                newpending.append(row); continue
            if v[candidate]==-1: v={c:-x for c,x in v.items()}
            # eliminate this new pivot from old transformed relations.
            for old in local.values():
                a=old['vec'].get(candidate,0)
                if a: axpy(old['vec'],a,v)
            local[candidate]={'vec':v,'source':row}
            chosen.append((candidate,row))
            progress=True
        pending=newpending
    assert len(local)==len(nonfree), (d,len(C),len(free),len(local),len(nonfree),len(pending))
    # Verify final normal form: pivot coefficient 1 and no other nonfree coordinate.
    for pc,obj in local.items():
        assert obj['vec'].get(pc)==1
        assert all(obj['vec'].get(c,0)==0 for c in nonfree if c!=pc)
    # Determinant of ORIGINAL chosen rows against complementary columns.
    chosen_by_pivot={p:row for p,row in chosen}
    ordered_nonfree=sorted(nonfree)
    M=[]
    for p in ordered_nonfree:
        row=chosen_by_pivot[p]
        tgt=set(row[2])
        M.append([1 if c in tgt else 0 for c in ordered_nonfree])
    det=bareiss_det(M)
    assert abs(det)==1,(d,det)
    block_records.append({'degree':d,'columns':[ps(c) for c in ordered_nonfree],
                          'free_columns':[ps(c) for c in free],
                          'selected_rows':[rid(k,mu) for p,(k,mu,t) in chosen if p in ordered_nonfree],
                          'determinant':det})
    for p,obj in local.items():
        pivots[p]=obj
        selected.append((p,obj))

assert len(selected)==421
# All pivot relations now have free tails only (within their degree), and all rows reduce to zero.
transformed=[]
for p,obj in sorted(selected,key=lambda z:(degree(z[0]),z[0])):
    tail={ps(c):-x for c,x in obj['vec'].items() if c!=p}
    assert all(c in F for c in obj['vec'] if c!=p)
    transformed.append({'pivot':ps(p),'source':rid(obj['source'][0],obj['source'][1]),'equation':tail})

reductions=[]
for k,mu,tgt in rows:
    v={c:1 for c in tgt}
    coeff={}
    # Because final pivot relations are identity on all nonfree columns, direct elimination is exact.
    for p,obj in sorted(selected,key=lambda z:(degree(z[0]),z[0])):
        a=v.get(p,0)
        if a:
            coeff[ps(p)]=a
            axpy(v,a,obj['vec'])
    assert not v,(rid(k,mu),v)
    reductions.append({'row':rid(k,mu),'equals_sum_of_transformed_pivots':{x:a for x,a in coeff.items() if a}})

certificate={
 'case':{'r':5,'q':6,'i':2,'j':2},
 'columns':len(cols),'nonzero_pieri_rows':len(rows),
 'free_family_F1':[ps(x) for x in sorted(F,key=lambda p:(degree(p),p))],
 'selected_pivots':len(selected),
 'global_complementary_minor_determinant': __import__('functools').reduce(lambda a,b:a*b,[b['determinant'] for b in block_records],1),
 'degree_block_unimodular_minors':block_records,
 'transformed_pivot_relations':transformed,
 'all_pieri_row_integral_reductions':reductions,
 'verification':{'all_rows_reduce_to_zero':True,'all_block_determinants_are_unit':True,
                 'relation_lattice_equals_selected_pieri_lattice':True}
}
print(json.dumps(certificate,separators=(',',':')))
